    "paymeWebhook.handle": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Internal server error";
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Method not found";
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        result: {
                            transactions: {
                                id: string | null;
                                time: number;
                                amount: number;
                                account: string;
                                create_time: number;
                                perform_time: number;
                                cancel_time: number;
                                transaction: string;
                                state: number;
                                reason: string | null;
                                receivers: null;
                            }[];
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Invalid statement period";
                            data: null;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        result: {
                            create_time: number;
                            perform_time: number;
                            cancel_time: number;
                            transaction: string;
                            state: number;
                            reason: string | null;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Transaction not found";
                            data: null;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        result: {
                            cancel_time: number;
                            transaction: string;
                            state: number;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Unable to cancel transaction";
                            data: null;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        result: {
                            create_time: number;
                            transaction: string;
                            /** @constant */
                            state: 1;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Order is awaiting payment by another transaction";
                            /** @constant */
                            data: "order_id";
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: null | [
                                string,
                                "Incorrect amount"
                            ] | [
                                string,
                                "Order not found",
                                "order_id"
                            ] | [
                                string,
                                "Order is not payable",
                                "order_id"
                            ] | [
                                string,
                                "Order already paid",
                                "order_id"
                            ] | [
                                string,
                                "Order is not payable via Payme",
                                "order_id"
                            ] | [
                                string,
                                "Topup already paid" | "Topup is not payable",
                                "order_id"
                            ];
                            message: string;
                            data: null;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Transaction timed out";
                            data: null;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Unable to perform operation";
                            data: null;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Transaction belongs to another order";
                            /** @constant */
                            data: "order_id";
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Order not found";
                            /** @constant */
                            data: "order_id";
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Transaction id is required";
                            data: null;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        result: {
                            allow: boolean;
                        };
                    } | {
                        /** @constant */
                        jsonrpc: "2.0";
                        id: unknown;
                        error: {
                            code: string;
                            /** @constant */
                            message: "Unauthorized merchant key";
                        };
                    };
                };
            };
        };
    };
